3	namespace App\Models\Retail;
4	
5	use App\Models\BaseModel;
6	use Illuminate\Database\Eloquent\Concerns\HasUuids;
7	
8	// V2: Simplified. Now only holds default_commission_rate and payout_hold_days. Per-product overrides moved to Shopify metafields.
9	class BrandStoreSettings extends BaseModel
10	{
11	    use HasUuids;
12	
13	    protected $table = 'brand.brand_store_settings';
14	
15	    protected $primaryKey = 'id';
16	
17	    public $incrementing = false;
18	
19	    protected $keyType = 'string';
20	
21	    protected $fillable = [
22	        'professional_id',
23	        'default_commission_rate',
24	        'payout_hold_days',
25	        'theme_id',
26	        'oxygen_storefront_id',
27	        'hydrogen_install_confirmed',
28	    ];
29	
30	    protected $hidden = [
31	        'oxygen_deployment_token',
32	    ];
33	
34	    protected $casts = [
35	        'default_commission_rate' => 'decimal:2',
36	        'payout_hold_days' => 'integer',
37	        'theme_id' => 'integer',
38	        // Encrypted at-rest using APP_KEY (AES-256-CBC via Laravel's encrypter)
39	        'oxygen_deployment_token' => 'encrypted',
40	    ];
41	
42	    /**
43	     * Effective hold days for this brand, respecting the system minimum.
44	     */
45	    public function getEffectivePayoutHoldDaysAttribute(): int
46	    {
47	        $min = (int) config('partna.store.min_payout_hold_days', 7);
48	        $systemDefault = (int) config('partna.store.payout_hold_days', 7);
49	
50	        $brandDays = $this->payout_hold_days;
51	
52	        if ($brandDays === null) {
53	            return max($min, $systemDefault);
54	        }
55	
56	        return max($min, $brandDays);
57	    }
58	
59	    /**
60	     * Reset all Shopify wizard progress fields.
61	     * Called on disconnect (dashboard) and app/uninstalled webhook so the
62	     * setup wizard starts fresh if the brand reconnects.
63	     */
64	    public static function clearWizardProgress(string $professionalId): void
65	    {
66	        static::where('professional_id', $professionalId)->update([
67	            'hydrogen_install_confirmed' => false,
68	            'oxygen_deployment_token' => null,
69	            'oxygen_storefront_id' => null,
70	        ]);
71	    }
72	}
