2	
3	namespace App\Http\Controllers\Api\Professional\Store;
4	
5	use App\Enums\BrandStatus;
6	use App\Http\Controllers\Api\ApiController;
7	use App\Http\Controllers\Concerns\ResolveCurrentProfessional;
8	use App\Http\Controllers\Concerns\ResolveCurrentSite;
9	use App\Http\Requests\Api\Professional\Store\UpdateBrandStoreSettingsRequest;
10	use App\Http\Resources\BrandStoreSettingsResource;
11	use App\Models\Core\Professional\BrandProfile;
12	use App\Models\Core\Site\Site;
13	use App\Models\Retail\BrandStoreSettings;
14	use App\Services\Cache\CacheKeyGenerator;
15	use App\Services\Cache\CacheLockService;
16	use App\Services\Hydrogen\HydrogenDeploymentService;
17	use App\Services\Professional\BrandStatusService;
18	use App\Services\Store\BrandCatalogService;
19	use Illuminate\Http\JsonResponse;
20	use Illuminate\Http\Request;
21	use Illuminate\Support\Arr;
22	use Illuminate\Support\Facades\Cache;
23	use Illuminate\Support\Facades\Http;
24	
25	class BrandStoreSettingsController extends ApiController
26	{
27	    use ResolveCurrentProfessional;
28	    use ResolveCurrentSite;
29	
30	    // V2: BrandResourcePolicy is registered for BrandStoreSettings — use authorizeForUser() if any
31	    // new action resolves a BrandStoreSettings by ID rather than by scoped query.
32	
33	    public function __construct(
34	        private readonly BrandCatalogService $catalogService,
35	        private readonly HydrogenDeploymentService $deployment,
36	        private readonly CacheLockService $cacheLock,
37	    ) {}
38	
39	    public function show(Request $request): JsonResponse
40	    {
41	        $pro = $this->currentProfessional($request);
42	
43	        $storeSettings = BrandStoreSettings::where('professional_id', $pro->id)->first();
44	
45	        $pro->loadMissing('site');
46	        $site = $pro->site;
47	        $siteSettings = is_array($site?->settings) ? $site->settings : [];
48	        $design = is_array($siteSettings['design'] ?? null) ? $siteSettings['design'] : [];
49	
50	        $metadata = [];
51	        try {
52	            $resolved = $this->catalogService->resolveBrandIntegration($pro);
53	            $metadata = $resolved['metadata'];
54	        } catch (\Throwable $e) {
55	        }
56	
57	        $brandProfile = BrandProfile::where('professional_id', $pro->id)->first();
58	
59	        return $this->success(new BrandStoreSettingsResource([
60	            'default_commission_rate' => $storeSettings?->default_commission_rate ?? config('partna.store.default_commission_rate', 15),
61	            'payout_hold_days' => $storeSettings?->payout_hold_days,
62	            'accent_color' => $design['accent_color'] ?? null,
63	            'theme_variant' => $design['theme_variant'] ?? null,
64	            'product_image_ratio' => $design['product_image_ratio'] ?? null,
65	            'custom_photos_enabled' => Arr::get($metadata, 'custom_photos_enabled', true),
66	            'custom_photo_position' => $design['custom_photo_position'] ?? 'after',
67	            'theme_id' => $storeSettings?->theme_id ?? 1,
68	            // Token is never returned; only expose whether one has been saved
69	            'oxygen_token_set' => ! empty($storeSettings?->oxygen_deployment_token),
70	            'oxygen_storefront_id' => $storeSettings?->oxygen_storefront_id,
71	            'hydrogen_install_confirmed' => (bool) ($storeSettings?->hydrogen_install_confirmed ?? false),
72	            'storefront_base_url' => 'https://'.($site?->subdomain ?? '').'.'.config('partna.public_domain', 'partna.au'),
73	            'storefront_status' => $storeSettings
74	                ? $this->cachedStorefrontStatus($pro->id, $site?->subdomain ?? '')
75	                : 'unreachable',
76	            'brand_status' => $brandProfile?->brand_status ?? BrandStatus::Onboarding->value,
77	        ]));
78	    }
79	
80	    public function update(UpdateBrandStoreSettingsRequest $request): JsonResponse
81	    {
82	        $pro = $this->currentProfessional($request);
83	
84	        $validated = $request->validated();
85	
86	        // 1. Local DB write for commission rate, payout hold days, and theme selection
87	        $dbFields = [];
88	        if (array_key_exists('default_commission_rate', $validated)) {
89	            $dbFields['default_commission_rate'] = $validated['default_commission_rate'];
90	        }
91	        if (array_key_exists('payout_hold_days', $validated)) {
92	            $dbFields['payout_hold_days'] = (int) $validated['payout_hold_days'];
93	        }
94	        if (array_key_exists('theme_id', $validated)) {
95	            $dbFields['theme_id'] = (int) $validated['theme_id'];
96	        }
97	        if (array_key_exists('oxygen_storefront_id', $validated)) {
98	            $dbFields['oxygen_storefront_id'] = $validated['oxygen_storefront_id'] ?: null;
99	        }
100	        if (array_key_exists('hydrogen_install_confirmed', $validated)) {
101	            $dbFields['hydrogen_install_confirmed'] = (bool) $validated['hydrogen_install_confirmed'];
102	        }
103	
104	        $hasOxygenToken = array_key_exists('oxygen_deployment_token', $validated);
105	
106	        if (! empty($dbFields) || $hasOxygenToken) {
107	            $settings = BrandStoreSettings::updateOrCreate(
108	                ['professional_id' => $pro->id],
109	                $dbFields
110	            );
111	            // Token is not in $fillable — set directly to avoid mass-assignment
112	            if ($hasOxygenToken) {
113	                $settings->oxygen_deployment_token = $validated['oxygen_deployment_token'] ?: null;
114	                $settings->save();
115	
116	                // Trigger a single-brand Oxygen deployment. Best-effort —
117	                // failures are logged but don't block the wizard.
118	                if (! empty($settings->oxygen_deployment_token)) {
119	                    $this->deployment->dispatchDeployment($pro->id);
120	                }
121	            }
122	        }
123	
124	        // 2. Write visual settings to site.settings.design
125	        $pro->loadMissing('site');
126	        $site = $pro->site;
127	
128	        // theme_id is also written to site.settings.design.default_theme so the
129	        // account data pipeline can read it without a separate store-settings fetch.
130	        $designFields = ['accent_color', 'theme_variant', 'product_image_ratio', 'custom_photo_position'];
131	        $designUpdates = [];
132	        foreach ($designFields as $field) {
133	            if (array_key_exists($field, $validated)) {
134	                $designUpdates[$field] = $validated[$field];
135	            }
136	        }
137	
138	        // Mirror theme_id into site.settings.design.default_theme for account data pipeline
139	        if (array_key_exists('theme_id', $validated)) {
140	            $designUpdates['default_theme'] = (int) $validated['theme_id'];
141	        }
142	
143	        if (! empty($designUpdates) && $site) {
144	            $settings = is_array($site->settings) ? $site->settings : [];
145	            $design = is_array($settings['design'] ?? null) ? $settings['design'] : [];
146	
147	            foreach ($designUpdates as $key => $value) {
148	                $design[$key] = $value;
149	            }
150	
151	            $settings['design'] = $design;
152	            $site->settings = $settings;
153	            $site->save();
154	        }
155	
156	        // Sync brand status after local mutations
157	        app(BrandStatusService::class)->sync($pro);
158	
159	        // 3. Shopify metafield sync — only when a Shopify-backed field is being updated.
160	        // Oxygen credentials are DB-only, so skip the Shopify block entirely for those patches
161	        // to avoid requiring an active Shopify integration.
162	        $shopifyFields = ['default_commission_rate', 'accent_color', 'theme_variant', 'product_image_ratio', 'custom_photos_enabled'];
163	        $needsShopifySync = (bool) array_intersect(array_keys($validated), $shopifyFields);
164	
165	        $freshMetadata = [];
166	        $integration = null;
167	
168	        if ($needsShopifySync) {
169	            try {
170	                $resolved = $this->catalogService->resolveBrandIntegration($pro);
171	                $integration = $resolved['integration'];
172	
173	                $shopMetafields = [];
174	                $metadataUpdates = [];
175	
176	                if (array_key_exists('default_commission_rate', $validated)) {
177	                    $shopMetafields[] = ['key' => 'default_commission_rate', 'value' => (string) $validated['default_commission_rate'], 'type' => 'number_decimal'];
178	                }
179	
180	                if (array_key_exists('accent_color', $validated)) {
181	                    $shopMetafields[] = ['key' => 'accent_color', 'value' => $validated['accent_color'] ?? '', 'type' => 'single_line_text_field'];
182	                }
183	
184	                if (array_key_exists('theme_variant', $validated)) {
185	                    $shopMetafields[] = ['key' => 'theme_variant', 'value' => $validated['theme_variant'] ?? '', 'type' => 'single_line_text_field'];
186	                }
187	
188	                if (array_key_exists('product_image_ratio', $validated)) {
189	                    $shopMetafields[] = ['key' => 'product_image_ratio', 'value' => $validated['product_image_ratio'] ?? '', 'type' => 'single_line_text_field'];
190	                }
191	
192	                // custom_photos_enabled stays in provider_metadata (feature toggle, not design)
193	                if (array_key_exists('custom_photos_enabled', $validated)) {
194	                    $metadataUpdates['custom_photos_enabled'] = (bool) $validated['custom_photos_enabled'];
195	                }
196	
197	                if (! empty($shopMetafields)) {
198	                    $result = $this->catalogService->setShopMetafields($integration, $shopMetafields);
199	
200	                    if (! $result['success']) {
201	                        $msg = $result['userErrors'][0]['message'] ?? 'Failed to update Shopify settings.';
202	
203	                        return $this->error($msg, 422);
204	                    }
205	                }
206	
207	                if (! empty($metadataUpdates)) {
208	                    $integration->mergeProviderMetadata($metadataUpdates);
209	                }
210	
211	                $freshMetadata = is_array($integration->provider_metadata) ? $integration->provider_metadata : [];
212	            } catch (\RuntimeException $e) {
213	                return $this->error($e->getMessage(), $e->getCode() ?: 502);
214	            } catch (\Throwable $e) {
215	                return $this->error('Unable to reach Shopify. Please try again.', 502);
216	            }
217	        }
218	
219	        // Return fresh state. Stash $site->fresh() once — calling it twice runs
220	        // two identical SELECTs against Supabase even though the second result
221	        // is byte-identical to the first.
222	        $storeSettings = BrandStoreSettings::where('professional_id', $pro->id)->first();
223	        $freshSite = $site?->fresh();
224	        $freshSiteSettings = is_array($freshSite?->settings) ? $freshSite->settings : [];
225	        $freshDesign = is_array($freshSiteSettings['design'] ?? null) ? $freshSiteSettings['design'] : [];
226	
227	        // When Shopify sync ran, use fresh metadata from integration; otherwise fall back to stored metadata
228	        if ($needsShopifySync && $integration) {
229	            $freshMetadata = is_array($integration->provider_metadata) ? $integration->provider_metadata : [];
230	        } else {
231	            try {
232	                $resolved = $this->catalogService->resolveBrandIntegration($pro);
233	                $freshMetadata = is_array($resolved['integration']->provider_metadata) ? $resolved['integration']->provider_metadata : [];
234	            } catch (\Throwable) {
235	                $freshMetadata = [];
236	            }
237	        }
238	
239	        return $this->success(new BrandStoreSettingsResource([
240	            'default_commission_rate' => $storeSettings?->default_commission_rate ?? config('partna.store.default_commission_rate', 15),
241	            'payout_hold_days' => $storeSettings?->payout_hold_days,
242	            'accent_color' => $freshDesign['accent_color'] ?? null,
243	            'theme_variant' => $freshDesign['theme_variant'] ?? null,
244	            'product_image_ratio' => $freshDesign['product_image_ratio'] ?? null,
245	            'custom_photos_enabled' => Arr::get($freshMetadata, 'custom_photos_enabled', true),
246	            'custom_photo_position' => $freshDesign['custom_photo_position'] ?? 'after',
247	            'theme_id' => $storeSettings?->theme_id ?? 1,
248	            'oxygen_token_set' => ! empty($storeSettings?->oxygen_deployment_token),
249	            'oxygen_storefront_id' => $storeSettings?->oxygen_storefront_id,
250	            'storefront_base_url' => 'https://'.($site?->subdomain ?? '').'.'.config('partna.public_domain', 'partna.au'),
251	            'storefront_status' => $storeSettings
252	                ? $this->cachedStorefrontStatus($pro->id, $site?->subdomain ?? '', forceRefresh: true)
253	                : 'unreachable',
254	        ]));
