257	    /**
258	     * Trigger an Oxygen deployment for this brand via GitHub Actions workflow_dispatch.
259	     *
260	     * Called from the dashboard wizard "Redeploy" button after the brand completes
261	     * domain setup (connecting the domain + setting it as primary in Shopify Hydrogen).
262	     */
263	    public function deploy(Request $request): JsonResponse
264	    {
265	        $pro = $this->currentProfessional($request);
266	
267	        $storeSettings = BrandStoreSettings::where('professional_id', $pro->id)->first();
268	
269	        if (! $storeSettings || empty($storeSettings->oxygen_deployment_token)) {
270	            return $this->error('No Oxygen deployment token saved. Please complete Oxygen setup first.', 400);
271	        }
272	
273	        // Deploys flip the storefront from unreachable → live; clear the cache
274	        // so the next show() probes fresh state instead of returning the
275	        // pre-deploy answer for up to 60s.
276	        Cache::forget(CacheKeyGenerator::brandStorefrontStatus($pro->id));
277	
278	        $this->deployment->dispatchDeployment($pro->id);
279	
280	        return $this->success(['message' => 'Deployment triggered. It usually takes 1–2 minutes.']);
281	    }
282	
283	    /**
284	     * Cache wrapper around checkStorefrontStatus(). The probe itself is a
285	     * synchronous outbound HTTP GET with 5s timeout — without this, every
286	     * /api/brand/store-settings read paid up to 8s of P95 latency on a slow
287	     * storefront. 60s TTL with SWR collapses that to one probe per minute
288	     * per brand. update() and deploy() bust the key so wizard transitions
289	     * surface immediately. Pass forceRefresh from write paths that want a
290	     * fresh probe but no read-side staleness.
291	     */
292	    private function cachedStorefrontStatus(
293	        string $professionalId,
294	        string $subdomain,
295	        bool $forceRefresh = false,
296	    ): string {
297	        $key = CacheKeyGenerator::brandStorefrontStatus($professionalId);
298	
299	        if ($forceRefresh) {
300	            Cache::forget($key);
301	            Cache::forget($key.':stale');
302	        }
303	
304	        return $this->cacheLock->rememberLocked(
305	            $key,
306	            60,
307	            fn () => $this->checkStorefrontStatus($subdomain),
308	        );
309	    }
310	
311	    /**
312	     * Check whether the storefront is reachable at its base URL.
313	     *
314	     * Makes a lightweight GET with redirects disabled so we can
315	     * distinguish "Hydrogen is serving" (2xx) from "Shopify is
316	     * falling through to the primary domain" (3xx redirect).
317	     *
318	     * @return 'live'|'redirecting'|'unreachable'
319	     */
320	    private function checkStorefrontStatus(string $subdomain): string
321	    {
322	        $url = 'https://'.$subdomain.'.'.config('partna.public_domain', 'partna.au');
323	
324	        try {
325	            $response = Http::withOptions([
326	                'allow_redirects' => false,
327	                'timeout' => 5,
328	                'connect_timeout' => 3,
329	            ])->get($url);
330	
331	            if ($response->successful()) {
332	                return 'live';
333	            }
334	
335	            if ($response->redirect()) {
336	                return 'redirecting';
337	            }
338	
339	            return 'unreachable';
340	        } catch (\Throwable) {
341	            return 'unreachable';
342	        }
343	    }
344	}
