11	// Internal endpoint called by the GitHub Actions deployment workflow.
12	// Returns all brands that have an Oxygen deployment token stored, so the workflow
13	// can build the Hydrogen bundle once and deploy it to every brand's Oxygen instance.
14	// The token is decrypted by the model's encrypted cast before being returned here —
15	// it is transmitted over HTTPS and only to the CI runner.
16	class HydrogenDeploymentController extends ApiController
17	{
18	    /**
19	     * Return brands with a stored Oxygen deployment token.
20	     *
21	     * When called from the GitHub Actions workflow_dispatch trigger for a
22	     * single-brand deploy, the optional ?professional_id= query parameter
23	     * filters to just that brand. Without it, all brands are returned for
24	     * the standard push-triggered deploy-everyone run.
25	     *
26	     * @return JsonResponse Array of {shop_domain, oxygen_deployment_token, oxygen_storefront_id}
27	     */
28	    public function targets(Request $request): JsonResponse
29	    {
30	        $query = BrandStoreSettings::query()
31	            ->whereNotNull('oxygen_deployment_token');
32	
33	        // Single-brand deploy: the workflow_dispatch trigger passes a
34	        // professional_id to filter to just the brand that saved credentials.
35	        if ($professionalId = $request->query('professional_id')) {
36	            $query->where('professional_id', $professionalId);
37	        }
38	
39	        $settings = $query->get(['professional_id', 'oxygen_deployment_token', 'oxygen_storefront_id']);
40	
41	        $targets = $settings->map(function (BrandStoreSettings $row) {
42	            // Resolve the shop domain from the brand's Shopify integration
43	            $integration = ProfessionalIntegration::query()
44	                ->where('professional_id', $row->professional_id)
45	                ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
46	                ->value('shopify_shop_domain');
47	
48	            return [
49	                'shop_domain' => $integration,
50	                // Decrypted by the encrypted cast — never stored in plain text
51	                'oxygen_deployment_token' => $row->oxygen_deployment_token,
52	                'oxygen_storefront_id' => $row->oxygen_storefront_id,
53	            ];
54	        })->values();
55	
56	        return $this->success($targets);
57	    }
58	}
