308	    /**
309	     * Return summary analytics for the brand dashboard overview panel.
310	     *
311	     * @return JsonResponse { data: { affiliate_count, total_commission_cents, currency_code,
312	     *                      commission_30d_cents, revenue_30d_cents,
313	     *                      recent_sales: [{affiliate_name, commission, occurred_at}] } }
314	     */
315	    public function overview(Request $request): JsonResponse
316	    {
317	        $professionalId = (string) $request->attributes->get('embedded_professional_id');
318	
319	        $affiliateCount = BrandPartnerLink::where('brand_professional_id', $professionalId)->count();
320	
321	        // Sum pending + approved commissions (not yet reversed).
322	        $commissionQuery = CommissionMovement::where('brand_professional_id', $professionalId)
323	            ->whereIn('status', ['pending', 'approved']);
324	
325	        $totalCommissionCents = (int) $commissionQuery->sum('amount_cents');
326	        $firstEntry = $commissionQuery->select('currency_code')->first();
327	        $currencyCode = $firstEntry ? (string) $firstEntry->currency_code : 'AUD';
328	
329	        $thirtyDaysAgo = now()->subDays(30);
330	
331	        // Commissions earned in the last 30 days (pending + approved).
332	        $commission30dCents = (int) CommissionMovement::where('brand_professional_id', $professionalId)
333	            ->whereIn('status', ['pending', 'approved'])
334	            ->where('occurred_at', '>=', $thirtyDaysAgo)
335	            ->sum('amount_cents');
336	
337	        // Revenue generated through affiliates in the last 30 days.
338	        // Derived from amount_cents / commission_rate so it works on entries
339	        // that pre-date the calculation_metadata.line_price_post_discount field.
340	        // commission_rate is stored as a percentage (e.g. 10 for 10%), and
341	        // amount_cents = lineTotal_dollars * commission_rate, so
342	        // revenue_cents = amount_cents * 100 / commission_rate.
343	        $revenue30dCents = (int) round((float) CommissionMovement::where('brand_professional_id', $professionalId)
344	            ->whereIn('status', ['pending', 'approved'])
345	            ->where('occurred_at', '>=', $thirtyDaysAgo)
346	            ->where('commission_rate', '>', 0)
347	            ->selectRaw('COALESCE(SUM(amount_cents * 100.0 / commission_rate), 0) as revenue_cents')
348	            ->value('revenue_cents'));
349	
350	        // Last 5 sales with affiliate display name from related Professional record.
351	        $recentSales = CommissionMovement::with('affiliateProfessional:id,display_name')
352	            ->where('brand_professional_id', $professionalId)
353	            ->whereIn('status', ['pending', 'approved'])
354	            ->orderByDesc('occurred_at')
355	            ->limit(5)
356	            ->get()
357	            ->map(fn ($entry) => [
358	                'affiliate_name' => (string) ($entry->affiliateProfessional?->display_name ?? 'Unknown'),
359	                // Format as decimal string (cents → dollars) with currency suffix.
360	                'commission' => number_format($entry->amount_cents / 100, 2).' '.($entry->currency_code ?? ''),
361	                'occurred_at' => $entry->occurred_at?->toIso8601String(),
362	            ])
363	            ->values()
364	            ->all();
365	
366	        return $this->success([
367	            'affiliate_count' => $affiliateCount,
368	            'total_commission_cents' => $totalCommissionCents,
369	            'currency_code' => $currencyCode,
370	            'commission_30d_cents' => $commission30dCents,
371	            'revenue_30d_cents' => $revenue30dCents,
372	            'recent_sales' => $recentSales,
373	        ]);
374	    }
