517	            // Subdomain input is validated but we use the brand's canonical site subdomain — not
518	            // this input — for security. The field is accepted to match client expectations.
519	            'subdomain' => ['required', 'string', 'regex:/^[a-z0-9][a-z0-9-]{0,62}$/'],
