598	    /**
599	     * Fully provision the Shopify integration using the embedded app's access token.
600	     *
601	     * Called from the Sidest-Embedded wizard immediately after the connection-code
602	     * step links the brand's Partna account to their Shopify store. The embedded
603	     * app has already completed Shopify OAuth and holds a fully-scoped access token
604	     * — storing it here gives the Partna backend everything it needs to run catalog
605	     * sync, webhook registration, and storefront token creation without requiring
606	     * the brand to also do a separate OAuth from the Partna dashboard.
607	     *
608	     * Safe to call multiple times (idempotent via updateOrCreate).
609	     *
610	     * @return JsonResponse { data: { provisioned: bool } }
611	     */
612	    public function provisionShopifyIntegration(Request $request): JsonResponse
613	    {
614	        $data = $request->validate([
615	            'access_token' => ['required', 'string', 'max:512'],
616	            'shop_id' => ['sometimes', 'nullable', 'string', 'max:255'],
617	            'scopes' => ['sometimes', 'nullable', 'string', 'max:4096'],
618	        ]);
619	
620	        $professionalId = (string) $request->attributes->get('embedded_professional_id');
621	        $professional = Professional::findOrFail($professionalId);
622	        $shopDomain = $this->normalizeShopDomain(
623	            strtolower(trim((string) $request->header('X-Shopify-Shop', '')))
624	        );
625	
626	        $existing = ProfessionalIntegration::query()
627	            ->where('professional_id', $professionalId)
628	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
629	            ->first();
630	
631	        $existingMetadata = is_array($existing?->provider_metadata) ? $existing->provider_metadata : [];
632	
633	        $scopesArray = [];
634	        if (! empty($data['scopes'])) {
635	            $scopesArray = array_values(array_filter(array_map(
636	                'trim',
637	                explode(',', (string) $data['scopes'])
638	            )));
639	        }
640	
641	        $metadata = array_merge($existingMetadata, [
642	            'shop_domain' => $shopDomain,
643	            'shop_id' => $data['shop_id'] ?? Arr::get($existingMetadata, 'shop_id'),
644	            'scopes' => $scopesArray ?: Arr::get($existingMetadata, 'scopes', []),
645	            'connected_at' => now()->toIso8601String(),
646	            'webhook_registration_state' => 'queued',
647	            'connected_via' => 'embedded_wizard',
648	        ]);
649	
650	        // Dispatch jobs only on first provision OR when a previous provision appears
651	        // incomplete. Two incomplete signals:
652	        //   1. webhook state is 'queued' — all jobs likely failed (e.g. bad token)
653	        //   2. collection handles are missing — metafields/collections jobs didn't finish
654	        $existingWebhookState = Arr::get($existingMetadata, 'webhook_registration_state', '');
655	        $collectionsIncomplete = empty(Arr::get($existingMetadata, 'active_collection_handle'))
656	            && empty(Arr::get($existingMetadata, 'default_collection_handle'));
657	        $needsJobDispatch = empty($existing?->access_token)
658	            || $existingWebhookState === 'queued'
659	            || $collectionsIncomplete;
660	
661	        // Detect a pure token-refresh no-op: integration already exists with the same
662	        // access token and setup is complete. The embedded app calls this on every
663	        // admin page load, so the no-op path must skip status sync + cache busting —
664	        // those are cross-region DB queries and Redis writes that nothing depends on
665	        // when the brand's underlying state is unchanged.
666	        $isNoOpRefresh = ! $needsJobDispatch
667	            && $existing !== null
668	            && $existing->access_token === $data['access_token'];
669	
670	        $integration = ProfessionalIntegration::updateOrCreate(
671	            [
672	                'professional_id' => $professionalId,
673	                'provider' => ProfessionalIntegration::PROVIDER_SHOPIFY,
674	            ],
675	            [
676	                'external_account_id' => $shopDomain,
677	                'access_token' => $data['access_token'],
678	                'last_catalog_sync_error' => null,
679	                'provider_metadata' => $metadata,
680	            ],
681	        );
682	
683	        BrandProfile::firstOrCreate(
684	            ['professional_id' => $professionalId],
685	            ['setup_complete' => false],
686	        );
687	
688	        // Dispatch setup jobs on initial provision or when the previous attempt
689	        // appears incomplete (webhook state still queued = jobs likely failed).
690	        // This endpoint fires on every embedded app load for token refreshes, so
691	        // guard carefully — successful setups must not re-queue jobs repeatedly.
692	        if ($needsJobDispatch) {
693	            $jobs = [
694	                RegisterShopifyWebhooksJob::class,
695	                CreateStorefrontAccessTokenJob::class,
696	                CreateShopifyMetafieldsJob::class,
697	                CreateShopifySalesChannelJob::class,
698	                SyncShopifyBrandDesignJob::class,
699	            ];
700	
701	            foreach ($jobs as $jobClass) {
702	                try {
703	                    $jobClass::dispatch((string) $integration->id);
704	                } catch (\Throwable $e) {
705	                    Log::warning('Failed to dispatch embedded integration setup job', [
706	                        'professional_id' => $professionalId,
707	                        'job' => class_basename($jobClass),
708	                        'message' => $e->getMessage(),
709	                    ]);
710	                }
711	            }
712	        }
713	
714	        // Skip cache invalidation + status sync on no-op token refreshes. Brand
715	        // status can't have changed when nothing about the integration changed,
716	        // and avoiding sync() saves ~8–12 cross-region DB queries per page load.
717	        if (! $isNoOpRefresh) {
718	            $this->cache->invalidateProfessional($professional);
719	            app(BrandStatusService::class)->sync($professional);
720	        }
721	
722	        return $this->success(['provisioned' => true]);
723	    }
