725	    /**
726	     * Check whether the storefront is reachable at its base URL.
727	     *
728	     * Makes a lightweight GET with redirects disabled. A 2xx response
729	     * means the storefront is serving pages directly. A 3xx redirect
730	     * is treated as "live" when it carries Oxygen/Hydrogen response
731	     * headers — the app code intentionally redirects the root (e.g.
732	     * Mode B redirecting to the Shopify store). Without those headers
733	     * the redirect is a domain misconfiguration (not primary).
734	     *
735	     * @return 'live'|'redirecting'|'unreachable'
736	     */
737	    private function checkStorefrontStatus(string $subdomain): string
738	    {
739	        $url = 'https://'.$subdomain.'.'.config('partna.public_domain', 'partna.au');
740	
741	        try {
742	            $response = Http::withOptions([
743	                'allow_redirects' => false,
744	                'timeout' => 5,
745	                'connect_timeout' => 3,
746	            ])->get($url);
747	
748	            if ($response->successful()) {
749	                return 'live';
750	            }
751	
752	            if ($response->redirect()) {
753	                // If the redirect comes from an Oxygen/Hydrogen deployment,
754	                // the storefront is live — the redirect is app-level logic
755	                // (e.g. root → Shopify store), not a domain misconfig.
756	                $poweredBy = $response->header('powered-by') ?? '';
757	                if (str_contains($poweredBy, 'Oxygen') || str_contains($poweredBy, 'Hydrogen')) {
758	                    return 'live';
759	                }
760	
761	                return 'redirecting';
762	            }
763	
764	            return 'unreachable';
765	        } catch (\Throwable) {
766	            return 'unreachable';
767	        }
768	    }
769	}
